<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neural Network Simulation</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: #05070f;
            overflow: hidden;
            font-family: monospace;
        }
        canvas {
            background-color: #05070f;
            box-shadow: 0 0 30px #101a3a;
            border: 1px solid rgba(0, 229, 255, 0.1);
        }
        #gui {
            position: absolute;
            top: 20px;
            left: 20px;
            z-index: 100;
            color: #ffd400;
            font-family: monospace;
            background-color: rgba(5, 7, 15, 0.8);
            border: 1px solid #ffd400;
            border-radius: 4px;
            padding: 10px;
            box-shadow: 0 0 15px #ffd400;
        }
        .dg.ac {
            background-color: rgba(5, 7, 15, 0.9) !important;
            border: 1px solid #ffd400 !important;
        }
        .dg .name {
            color: #ffd400 !important;
        }
        .dg .value {
            color: #00e5ff !important;
        }
        .dg .button {
            background-color: #101a3a !important;
            border: 1px solid #ffd400 !important;
            color: #ffd400 !important;
        }
        .dg .button:hover {
            background-color: #00e5ff !important;
            color: #05070f !important;
        }
    </style>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
</head>
<body>
    <canvas id="canvas" width="800" height="800"></canvas>
    <div id="gui"></div>

    <script>
        // Canvas setup
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        // Neon color palette
        const colors = {
            background: '#05070f',
            backgroundGlow: '#101a3a',
            mainBranch: '#00e5ff',
            accentBranch: '#d6ff00',
            synapse: '#ff2bd6',
            pulse: '#fff36a',
            ui: '#ffd400',
            scanline: 'rgba(0, 229, 255, 0.08)'
        };

        // Simulation parameters
        const params = {
            neuronCount: 4,
            branchGrowthSpeed: 1.5,
            maxBranchDepth: 6,
            branchSplitChance: 0.3,
            branchCurvature: 0.5,
            maxBranchLength: 120,
            synapseDistanceThreshold: 15,
            synapseGlowStrength: 8,
            pulseSpeed: 2.0,
            pulseFrequency: 0.03,
            pulseBrightness: 0.8,
            backgroundColor: colors.background,
            branchColor: colors.mainBranch,
            accentBranchColor: colors.accentBranch,
            synapseColor: colors.synapse,
            pulseColor: colors.pulse
        };

        // Simulation state
        let neurons = [];
        let synapses = [];
        let pulses = [];
        let isAnimating = true;
        let frameCount = 0;

        // Initialize the simulation
        function init() {
            // Clear existing data
            neurons = [];
            synapses = [];
            pulses = [];

            // Create seed neurons near center
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            for (let i = 0; i < params.neuronCount; i++) {
                const angle = (Math.PI * 2 / params.neuronCount) * i;
                const distance = 30 + Math.random() * 20;

                neurons.push({
                    x: centerX + Math.cos(angle) * distance,
                    y: centerY + Math.sin(angle) * distance,
                    depth: 0,
                    branches: [],
                    active: true
                });
            }

            // Create initial pulses on some branches
            for (let i = 0; i < Math.min(neurons.length, 3); i++) {
                if (neurons[i].branches.length > 0) {
                    const branch = neurons[i].branches[0];
                    pulses.push({
                        branchId: branch.id,
                        position: 0.1,
                        speed: params.pulseSpeed,
                        brightness: params.pulseBrightness,
                        active: true
                    });
                }
            }
        }

        // Generate a random color from the palette
        function getRandomColor() {
            return Math.random() > 0.7 ? params.accentBranchColor : params.branchColor;
        }

        // Grow branches recursively
        function growBranches() {
            if (!isAnimating) return;

            for (let neuron of neurons) {
                if (!neuron.active) continue;

                // If no branches yet, create first branch
                if (neuron.branches.length === 0) {
                    const angle = Math.random() * Math.PI * 2;
                    const length = 10 + Math.random() * 30;

                    neuron.branches.push({
                        id: Date.now() + Math.random(),
                        x1: neuron.x,
                        y1: neuron.y,
                        x2: neuron.x + Math.cos(angle) * length,
                        y2: neuron.y + Math.sin(angle) * length,
                        thickness: 1 + Math.random() * 1.5,
                        color: getRandomColor(),
                        curvature: (Math.random() - 0.5) * params.branchCurvature,
                        length: length,
                        depth: 1
                    });
                }

                // Grow existing branches
                for (let i = neuron.branches.length - 1; i >= 0; i--) {
                    const branch = neuron.branches[i];

                    // Skip if already at max depth or length
                    if (branch.depth >= params.maxBranchDepth || branch.length >= params.maxBranchLength) {
                        continue;
                    }

                    // Calculate growth direction with curvature
                    const dx = branch.x2 - branch.x1;
                    const dy = branch.y2 - branch.y1;
                    const length = Math.sqrt(dx * dx + dy * dy);

                    if (length === 0) continue;

                    const dirX = dx / length;
                    const dirY = dy / length;

                    // Add random variation
                    const angle = Math.atan2(dirY, dirX) + (Math.random() - 0.5) * 0.3;
                    const growth = params.branchGrowthSpeed;

                    // Update branch end point
                    branch.x1 = branch.x2;
                    branch.y1 = branch.y2;
                    branch.x2 = branch.x2 + Math.cos(angle) * growth;
                    branch.y2 = branch.y2 + Math.sin(angle) * growth;

                    // Increase length
                    branch.length += growth;

                    // Check if we should split
                    if (Math.random() < params.branchSplitChance && branch.depth < params.maxBranchDepth - 1) {
                        const splitAngle1 = angle + Math.PI / 4 + (Math.random() - 0.5) * 0.5;
                        const splitAngle2 = angle - Math.PI / 4 + (Math.random() - 0.5) * 0.5;

                        const splitLength = 5 + Math.random() * 20;

                        // Create two new branches
                        neuron.branches.push({
                            id: Date.now() + Math.random(),
                            x1: branch.x2,
                            y1: branch.y2,
                            x2: branch.x2 + Math.cos(splitAngle1) * splitLength,
                            y2: branch.y2 + Math.sin(splitAngle1) * splitLength,
                            thickness: 0.8 + Math.random() * 1,
                            color: getRandomColor(),
                            curvature: (Math.random() - 0.5) * params.branchCurvature,
                            length: splitLength,
                            depth: branch.depth + 1
                        });

                        neuron.branches.push({
                            id: Date.now() + Math.random(),
                            x1: branch.x2,
                            y1: branch.y2,
                            x2: branch.x2 + Math.cos(splitAngle2) * splitLength,
                            y2: branch.y2 + Math.sin(splitAngle2) * splitLength,
                            thickness: 0.8 + Math.random() * 1,
                            color: getRandomColor(),
                            curvature: (Math.random() - 0.5) * params.branchCurvature,
                            length: splitLength,
                            depth: branch.depth + 1
                        });
                    }
                }
            }

            // Detect synapses
            detectSynapses();
        }

        // Detect when branch tips are close enough to form synapses
        function detectSynapses() {
            // Check all branch endpoints against each other
            for (let i = 0; i < neurons.length; i++) {
                const neuron = neurons[i];
                for (let j = 0; j < neuron.branches.length; j++) {
                    const branch1 = neuron.branches[j];
                    const x1 = branch1.x2;
                    const y1 = branch1.y2;

                    // Check against all other branches
                    for (let k = 0; k < neurons.length; k++) {
                        const otherNeuron = neurons[k];
                        for (let l = 0; l < otherNeuron.branches.length; l++) {
                            const branch2 = otherNeuron.branches[l];
                            const x2 = branch2.x2;
                            const y2 = branch2.y2;

                            // Skip if same branch
                            if (branch1.id === branch2.id) continue;

                            // Calculate distance
                            const dx = x2 - x1;
                            const dy = y2 - y1;
                            const distance = Math.sqrt(dx * dx + dy * dy);

                            // Check if within threshold and not already connected
                            if (distance < params.synapseDistanceThreshold) {
                                // Check if synapse already exists between these two branches
                                let exists = false;
                                for (let synapse of synapses) {
                                    if ((synapse.branch1 === branch1.id && synapse.branch2 === branch2.id) || 
                                        (synapse.branch1 === branch2.id && synapse.branch2 === branch1.id)) {
                                        exists = true;
                                        break;
                                    }
                                }

                                if (!exists) {
                                    // Create synapse
                                    synapses.push({
                                        branch1: branch1.id,
                                        branch2: branch2.id,
                                        x: (x1 + x2) / 2,
                                        y: (y1 + y2) / 2,
                                        distance: distance,
                                        glow: 0,
                                        pulse: 0
                                    });

                                    // Add a pulse to the new synapse
                                    pulses.push({
                                        branchId: branch1.id,
                                        position: 0.5,
                                        speed: params.pulseSpeed,
                                        brightness: params.pulseBrightness,
                                        active: true
                                    });
                                }
                            }
                        }
                    }
                }
            }
        }

        // Animate pulses
        function animatePulses() {
            for (let i = pulses.length - 1; i >= 0; i--) {
                const pulse = pulses[i];

                // Find which branch this pulse is on
                let foundBranch = false;
                let branch;

                // Search through all branches
                for (let neuron of neurons) {
                    for (let b of neuron.branches) {
                        if (b.id === pulse.branchId) {
                            branch = b;
                            foundBranch = true;
                            break;
                        }
                    }
                    if (foundBranch) break;
                }

                if (!foundBranch) {
                    pulses.splice(i, 1);
                    continue;
                }

                // Update pulse position
                pulse.position += pulse.speed * 0.01;

                // If pulse reaches end, create new pulse on connected branch or remove
                if (pulse.position >= 1) {
                    // Find connected branches
                    let connectedBranches = [];

                    // Find synapses connected to this branch
                    for (let synapse of synapses) {
                        if (synapse.branch1 === pulse.branchId) {
                            connectedBranches.push(synapse.branch2);
                        } else if (synapse.branch2 === pulse.branchId) {
                            connectedBranches.push(synapse.branch1);
                        }
                    }

                    if (connectedBranches.length > 0) {
                        // Choose a random connected branch
                        const nextBranchId = connectedBranches[Math.floor(Math.random() * connectedBranches.length)];

                        // Create new pulse on the connected branch
                        pulses.push({
                            branchId: nextBranchId,
                            position: 0.1,
                            speed: params.pulseSpeed,
                            brightness: params.pulseBrightness,
                            active: true
                        });
                    }

                    // Remove the old pulse
                    pulses.splice(i, 1);
                }
            }

            // Animate synapse glow
            for (let synapse of synapses) {
                synapse.glow += Math.sin(frameCount * params.pulseFrequency) * 0.1;
                synapse.glow = Math.max(0, Math.min(1, synapse.glow));
            }
        }

        // Render the scene
        function render() {
            // Clear canvas with a slight fade for motion trail
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = 'rgba(5, 7, 15, 0.1)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw scanlines
            ctx.globalAlpha = 0.1;
            ctx.strokeStyle = colors.scanline;
            ctx.lineWidth = 1;
            for (let y = 0; y < canvas.height; y += 4) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(canvas.width, y);
                ctx.stroke();
            }
            ctx.globalAlpha = 1;

            // Draw branches
            for (let neuron of neurons) {
                for (let branch of neuron.branches) {
                    // Draw branch with glow
                    ctx.strokeStyle = branch.color;
                    ctx.lineWidth = branch.thickness;
                    ctx.shadowColor = branch.color;
                    ctx.shadowBlur = 5;

                    ctx.beginPath();
                    ctx.moveTo(branch.x1, branch.y1);

                    // Use quadratic curve for organic look
                    const dx = branch.x2 - branch.x1;
                    const dy = branch.y2 - branch.y1;
                    const midX = branch.x1 + dx / 2 + (Math.random() - 0.5) * branch.curvature * 50;
                    const midY = branch.y1 + dy / 2 + (Math.random() - 0.5) * branch.curvature * 50;

                    ctx.quadraticCurveTo(midX, midY, branch.x2, branch.y2);
                    ctx.stroke();

                    // Reset shadow
                    ctx.shadowBlur = 0;
                }
            }

            // Draw synapses
            for (let synapse of synapses) {
                ctx.globalAlpha = 0.8 + synapse.glow * 0.2;
                ctx.fillStyle = colors.synapse;
                ctx.shadowColor = colors.synapse;
                ctx.shadowBlur = params.synapseGlowStrength * (1 + synapse.glow);

                ctx.beginPath();
                ctx.arc(synapse.x, synapse.y, 3, 0, Math.PI * 2);
                ctx.fill();

                ctx.shadowBlur = 0;
                ctx.globalAlpha = 1;
            }

            // Draw pulses
            for (let pulse of pulses) {
                // Find the branch this pulse is on
                let foundBranch = false;
                let branch;

                for (let neuron of neurons) {
                    for (let b of neuron.branches) {
                        if (b.id === pulse.branchId) {
                            branch = b;
                            foundBranch = true;
                            break;
                        }
                    }
                    if (foundBranch) break;
                }

                if (!foundBranch) continue;

                // Calculate position along the branch
                const dx = branch.x2 - branch.x1;
                const dy = branch.y2 - branch.y1;
                const length = Math.sqrt(dx * dx + dy * dy);

                if (length === 0) continue;

                const x = branch.x1 + (dx * pulse.position);
                const y = branch.y1 + (dy * pulse.position);

                // Draw pulse with glow
                ctx.globalAlpha = pulse.brightness;
                ctx.fillStyle = colors.pulse;
                ctx.shadowColor = colors.pulse;
                ctx.shadowBlur = 15;

                ctx.beginPath();
                ctx.arc(x, y, 2, 0, Math.PI * 2);
                ctx.fill();

                ctx.shadowBlur = 0;
                ctx.globalAlpha = 1;
            }

            // Draw vignette
            const gradient = ctx.createRadialGradient(
                canvas.width / 2, canvas.height / 2, 0,
                canvas.width / 2, canvas.height / 2, canvas.width / 2
            );
            gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
            gradient.addColorStop(1, 'rgba(0, 0, 0, 0.5)');

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        // Animation loop
        function animate() {
            if (isAnimating) {
                growBranches();
                animatePulses();
            }
            render();

            frameCount++;
            requestAnimationFrame(animate);
        }

        // Initialize GUI
        function setupGUI() {
            const gui = new dat.GUI({ autoPlace: false });
            document.getElementById('gui').appendChild(gui.domElement);

            // Create folders
            const growthFolder = gui.addFolder('Growth');
            const synapsesFolder = gui.addFolder('Synapses');
            const pulsesFolder = gui.addFolder('Pulses');
            const visualsFolder = gui.addFolder('Visuals');

            // Growth controls
            growthFolder.add(params, 'neuronCount', 3, 6, 1).name('Neuron Count');
            growthFolder.add(params, 'branchGrowthSpeed', 0.5, 3, 0.1).name('Branch Growth Speed');
            growthFolder.add(params, 'maxBranchDepth', 2, 8, 1).name('Max Branch Depth');
            growthFolder.add(params, 'branchSplitChance', 0.1, 0.7, 0.05).name('Branch Split Chance');
            growthFolder.add(params, 'branchCurvature', 0, 1, 0.1).name('Branch Curvature');
            growthFolder.add(params, 'maxBranchLength', 50, 200, 5).name('Max Branch Length');

            // Synapses controls
            synapsesFolder.add(params, 'synapseDistanceThreshold', 5, 50, 1).name('Synapse Distance Threshold');
            synapsesFolder.add(params, 'synapseGlowStrength', 1, 15, 0.5).name('Synapse Glow Strength');

            // Pulses controls
            pulsesFolder.add(params, 'pulseSpeed', 0.5, 5, 0.1).name('Pulse Speed');
            pulsesFolder.add(params, 'pulseFrequency', 0.01, 0.1, 0.005).name('Pulse Frequency');
            pulsesFolder.add(params, 'pulseBrightness', 0.3, 1, 0.1).name('Pulse Brightness');

            // Visual controls
            visualsFolder.addColor(params, 'backgroundColor').name('Background Color');
            visualsFolder.addColor(params, 'branchColor').name('Branch Color');
            visualsFolder.addColor(params, 'accentBranchColor').name('Accent Branch Color');
            visualsFolder.addColor(params, 'synapseColor').name('Synapse Color');
            visualsFolder.addColor(params, 'pulseColor').name('Pulse Color');

            // Add buttons
            gui.add({ regenerate: () => init() }, 'regenerate').name('Regenerate Network');
            gui.add({ clear: () => {
                neurons = [];
                synapses = [];
                pulses = [];
            } }, 'clear').name('Clear Canvas');

            gui.add({ toggle: () => isAnimating = !isAnimating }, 'toggle').name('Pause/Resume');

            // Close all folders by default
            growthFolder.close();
            synapsesFolder.close();
            pulsesFolder.close();
            visualsFolder.close();
        }

        // Initialize everything
        init();
        setupGUI();
        animate();
    </script>
</body>
